questionvariables.text:
/* Define the set A */ 
element:rand_with_step(4,100,2);
element1:rand(10)+3;


/* correct answers */
number_correct:rand(3)+1;
corr_ans: rand_selection([
[1, true, sconcat("A population of bacteria decreases by a factor of \\(\\displaystyle \\frac{1}{",element,"} \\) every \\(24\\) hours")],
[2, true, "The value of a car decreases by \\(10\\%\\) every year"],
[3, true, "The number of conference attendees doubles yearly"],
[4, true, "The intensity of a radioactive substance decreases by half every \\(10\\) years"]], number_correct);

/* incorrect answers */
number_incorrect:5-number_correct;
incorr_ans: rand_selection([
[5, false, sconcat("For each training session, a personal trainer charges his clients \\(\\mbox{N}\\$",element1,"\\) less than the previous training session")],
[6, false, "A plant grows by \\(3\\) \\(\\mbox{cm}\\) each week"],
[7, false, "The temperature drops by \\(2\\) degrees Celsius every hour during the night"],
[8, false, "The speed of a car increases by \\(5\\) \\(\\mbox{km/h}\\) every minute during acceleration"]], number_incorrect);


ma: random_permutation(append(corr_ans, incorr_ans));
/*Worked Soln*/
ta_index: sort(makelist(x[1], x, ma));

feedbackvariables.text:
/*Node 1: Checks for the correct answer*/

/*Node 2: Checks if option 5 (incorrect) was provided and selected*/
true_opt_5:if member(5,ta_index) then ( if member(5,ans2) then 1 else 0 ) else 0;

/*Node 3: Checks if option 6 (incorrect) was provided and selected*/
true_opt_6:if member(6,ta_index) then ( if member(6,ans2) then 1 else 0 ) else 0;

/*Node 4: Checks if option 7 (incorrect) was provided and selected*/
true_opt_7:if member(7,ta_index) then ( if member(7,ans2) then 1 else 0 ) else 0;

/*Node 5: Checks if option 8 (incorrect) was provided and selected*/
true_opt_8:if member(8,ta_index) then ( if member(8,ans2) then 1 else 0 ) else 0;
